import { z } from 'zod';
import { ANONYMOUS_TOOLS, TOOLS, type ToolDefinition } from './tools.js';

/**
 * App hosting P2: the hosting MCP's tool registry as DATA — for the machine docs (`/docs/apps/mcp.md`)
 * and the directory submission packs (`docs/apps/directory/`, generated by `scripts/directory-pack.ts`
 * and checked by a test), so neither can drift from what `tools/list` actually answers.
 */

export type ToolSurface = 'remote' | 'local' | 'anonymous';

export type ToolCatalogueEntry = {
  name: string;
  title: string;
  description: string;
  /** The OAuth scope a grant needs (none on the anonymous endpoint). */
  scope: string | null;
  readOnlyHint: boolean;
  destructiveHint: boolean;
  idempotentHint: boolean;
  openWorldHint: boolean;
  /** remote: the OAuth endpoint (and stdio); local: `create mcp` only; anonymous: the unauthenticated endpoint only. */
  surface: ToolSurface;
  inputSchema: Record<string, unknown>;
};

function entry(t: ToolDefinition, surface: ToolSurface): ToolCatalogueEntry {
  const schema = z.toJSONSchema(t.input, { io: 'input' }) as Record<string, unknown>;
  delete schema.$schema;
  return {
    name: t.name,
    title: t.title,
    description: t.description,
    scope: surface === 'anonymous' ? null : t.scope,
    readOnlyHint: t.annotations.readOnlyHint,
    destructiveHint: t.annotations.destructiveHint,
    idempotentHint: t.annotations.idempotentHint,
    openWorldHint: t.annotations.openWorldHint,
    surface,
    inputSchema: schema,
  };
}

export function toolCatalogue(): ToolCatalogueEntry[] {
  return [...TOOLS.map((t) => entry(t, t.available ? 'local' : 'remote')), ...ANONYMOUS_TOOLS.map((t) => entry(t, 'anonymous'))];
}

const kind = (t: ToolCatalogueEntry) => (t.destructiveHint ? 'destructive' : t.readOnlyHint ? 'read' : 'write');
const cell = (text: string) => text.replace(/\|/g, '\\|').replace(/\n/g, ' ');

/** A markdown table of one surface's tools: name, title, kind, scope, and the model-facing description. */
export function toolTableMarkdown(surface: ToolSurface | 'signed-in'): string {
  const rows = toolCatalogue().filter((t) => (surface === 'signed-in' ? t.surface !== 'anonymous' : t.surface === surface));
  return [
    '| Tool | Title | Kind | Scope | Does |',
    '|---|---|---|---|---|',
    ...rows.map((t) => `| ${t.name}${t.surface === 'local' ? ' (create mcp only)' : ''} | ${cell(t.title)} | ${kind(t)} | ${t.scope ?? 'none'} | ${cell(t.description)} |`),
  ].join('\n');
}
